local function Bark(creature)
    local lines = BARKS[creature:GetEntry()]
    if not lines or not creature:IsAlive() or creature:IsInCombat() then return end
    local near = creature:GetPlayersInRange(30)
    if not near or #near == 0 then return end
    pcall(function() creature:SendUnitSay(lines[math.random(#lines)], 0) end)
end

local last = {}
local function WeakestAlly(creature, pct)
    local best, bp = nil, pct
    local mine = creature:GetFaction()
    local ok, list = pcall(function() return creature:GetCreaturesInRange(30) end)
    if ok and list then
        for _, c in ipairs(list) do
            if c:IsAlive() and c:GetFaction() == mine then
                local hp = c:GetHealthPct()
                if hp < bp then best, bp = c, hp end
            end
        end
    end
    local me = creature:GetHealthPct()
    if me < bp then best = creature end
    return best
end

local function CastTick(_, _, _, creature)
    if not creature or not creature:IsAlive() or not creature:IsInCombat() then return end
    local kit = KITS[creature:GetEntry()]
    local victim = creature:GetVictim()
    if not kit or not victim then return end
    local g = creature:GetGUIDLow()
    last[g] = last[g] or {}
    local now = os.time()
    local hp = creature:GetHealthPct()
    for i, k in ipairs(kit) do
        if (last[g][i] or 0) <= now then
            local mode, did = k[5] or "dmg", false
            if mode == "self" or mode == "enrage" then
                if hp < (k[6] or 60) then
                    did = pcall(function() if k[2] then creature:CastCustomSpell(creature, k[1], true, k[2], 0, 0) else creature:CastSpell(creature, k[1], true) end end)
                end
            elseif mode == "heal" then
                local ally = WeakestAlly(creature, k[6] or 65)
                if ally then did = pcall(function() creature:CastCustomSpell(ally, k[1], true, k[2] or 1000, 0, 0) end) end
            else
                did = pcall(function() if k[2] then creature:CastCustomSpell(victim, k[1], true, math.floor(k[2] * 0.7), 0, 0) else creature:CastSpell(victim, k[1], true) end end)
            end
            if did then last[g][i] = now + math.random(k[3], k[4]) break end
        end
    end
    creature:RegisterEvent(CastTick, 2500, 1)
end

-- the groups were baked with estimated heights: once spawned, each one is put on the real ground (and the corrected height is saved for the next start)
local function Snap(c)
    local g = c:GetDBTableGUIDLow()
    if not ((g >= 3100400001 and g <= 3100599999) or g == 3100700002 or (g >= 3100800001 and g <= 3100899999)) then return end
    local x, y, z, o = c:GetLocation()
    local ok, h = pcall(function() return c:GetMap():GetHeight(x, y, c) end)
    if ok and h and math.abs(h - z) > 1.2 and math.abs(h - z) < 90 then
        pcall(function() c:SetHomePosition(x, y, h + 0.1, o) end)
        pcall(function() c:NearTeleport(x, y, h + 0.1, o) end)
        pcall(WorldDBExecute, string.format("UPDATE creature SET position_z = %.3f WHERE guid = %d", h + 0.1, g))
    end
end

local function OnSpawn(_, creature)
    Snap(creature)
    if BARKS[creature:GetEntry()] then
        creature:RegisterEvent(function(_, _, _, c) Bark(c) end, math.random(40000, 90000), 0)
    end
end
local function OnEnter(_, creature, target)
    local y = YELLS[creature:GetEntry()]
    if y then pcall(function() creature:SendUnitYell(y[1], 0) end) end
    if KITS[creature:GetEntry()] then creature:RegisterEvent(CastTick, 3000, 1) end
end
local function OnLeave(_, creature) last[creature:GetGUIDLow()] = nil creature:RemoveEvents() if BARKS[creature:GetEntry()] then creature:RegisterEvent(function(_, _, _, c) Bark(c) end, math.random(40000, 90000), 0) end end
local function OnDied(_, creature, killer)
    local y = YELLS[creature:GetEntry()]
    if y then pcall(function() creature:SendUnitYell(y[2], 0) end) end
    last[creature:GetGUIDLow()] = nil
    creature:RemoveEvents()
end

